public class Main {
    public static void main(String[] args) {
        String memberName = "Neha Gupta";
        char tier = 'A';
        boolean isActive = true;
        System.out.println("Member: " + memberName + " | Tier: " + tier + " | Active: " + isActive);
    }
}

public class Main {
    public static void main(String[] args) {
        char rupee = '₹';
        int price = 499;
        System.out.println("Price: " + rupee + price);
    }
}

public class Main {
    public static void main(String[] args) {
        String course = "B.Tech CSE";
        int semester = 4;
        double cgpa = 8.92;
        System.out.println("Course: " + course + " (Sem " + semester + ") - CGPA: " + cgpa);
    }
}

public class Main {
    public static void main(String[] args) {
        char ch = 'A';
        int nextCode = ch + 1;
        char nextChar = (char) nextCode;
        System.out.println("Original: " + ch + " | Next: " + nextChar);
    }
}

public class Main {
    public static void main(String[] args) {
        int attendancePercentage = 82;
        boolean isEligible = attendancePercentage >= 75;
        System.out.println("Attendance: " + attendancePercentage + "% | Exam Eligible: " + isEligible);
    }
}
